from .model import CbtsModel
from .provider import Provider
from .collector import create_configuration_data


class cbts(object):

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self, bts_yaml='config_bts.yaml', net_yaml='config_ext_net.yaml',
                 flavors_yaml='config_flavor.yaml', bts_env='config_bts.env',
                 net_env='config_ext_net.env'):

        self.cbts_provider = Provider(bts_yaml=bts_yaml,
                                      net_yaml=net_yaml,
                                      flavors_yaml=flavors_yaml,
                                      bts_env=bts_env,
                                      net_env=net_env)

    def read_config_from_files(self, cfg_dirpath):
        """ Load CbtsModel using configuration files. There is assumption that
        env following env files are available: `config_bts.env,
        config_ext_net.env`.

        :cfg_dirpath: absolute or relative path to directory containing config
        files """
        return self.cbts_provider.read_from_files(cfg_dirpath)

    def create_empty_cbts(self):
        """ Create empty CbtsModel, there will be no single variable set. It
        allows to load empty model without usage of template files.  """
        return CbtsModel(None, None, None)

    def create_configuration_data(self,
                                  environment_filepaths,
                                  deep_merge_enabled=False,
                                  merge_strings_enabled=False):
        # type: (list, bool, bool) -> dict
        """ Creates heat stack configuration data as dictionary. It is possible
        to pass multiple environment files. By default, the keyword will not
        `deep merge` the configuration. """
        return create_configuration_data(
            environment_filepaths=environment_filepaths,
            deep_merge_enabled=deep_merge_enabled,
            merge_strings_enabled=merge_strings_enabled)


class CbtsProvider(object):
    def __init__(self, bts_yaml='config_bts.yaml', net_yaml='config_ext_net.yaml',
                 flavors_yaml='config_flavor.yaml', bts_env='config_bts.env',
                 net_env='config_ext_net.env'):

        self.provider = Provider(bts_yaml=bts_yaml,
                                 net_yaml=net_yaml,
                                 flavors_yaml=flavors_yaml,
                                 bts_env=bts_env,
                                 net_env=net_env)

    def read_from_files(self, cfg_dirpath):
        """ Load CbtsModel using configuration files. There is assumption that
        env following env files are available: `config_bts.env,
        config_ext_net.env`.

        :cfg_dirpath: absolute or relative path to directory containing config
        files """
        return self.provider.read_from_files(cfg_dirpath)
